// Catcoder Core Engine Fixes – Oberfläche (ES-Modul)
export function activate(host, ctx) {
  const off = [];
  off.push(host.ui.registerNavigation({ id: ctx.id, label: "Core Engine", page: { id: ctx.id }, icon: "activity", order: 60 }));
  off.push(host.ui.registerPage({ id: ctx.id, label: "Core Engine Fixes", mount(el) {
    el.innerHTML = `
      <div class="pl-${ctx.id}">
        <header class="pl-${ctx.id}__header">
          <h1>Catcoder Core Engine</h1>
          <p class="pl-${ctx.id}__subtitle">Überwachung und Steuerung der Agenten-Engine</p>
        </header>

        <section class="pl-${ctx.id}__section">
          <h2>Status-Übersicht</h2>
          <div class="pl-${ctx.id}__grid">
            <div class="pl-${ctx.id}__card">
              <div class="pl-${ctx.id}__card-icon">${host.ui.icon("git-commit")}</div>
              <div class="pl-${ctx.id}__card-content">
                <span class="pl-${ctx.id}__card-label">Aktive Goals</span>
                <span class="pl-${ctx.id}__card-value" id="pl-${ctx.id}__active-goals">0</span>
              </div>
            </div>
            <div class="pl-${ctx.id}__card">
              <div class="pl-${ctx.id}__card-icon">${host.ui.icon("alert-circle")}</div>
              <div class="pl-${ctx.id}__card-content">
                <span class="pl-${ctx.id}__card-label">Review-Blockaden</span>
                <span class="pl-${ctx.id}__card-value" id="pl-${ctx.id}__review-blocked">0</span>
              </div>
            </div>
            <div class="pl-${ctx.id}__card">
              <div class="pl-${ctx.id}__card-icon">${host.ui.icon("refresh-cw")}</div>
              <div class="pl-${ctx.id}__card-content">
                <span class="pl-${ctx.id}__card-label">Planning-Loops</span>
                <span class="pl-${ctx.id}__card-value" id="pl-${ctx.id}__planning-loops">0</span>
              </div>
            </div>
            <div class="pl-${ctx.id}__card">
              <div class="pl-${ctx.id}__card-icon">${host.ui.icon("users")}</div>
              <div class="pl-${ctx.id}__card-content">
                <span class="pl-${ctx.id}__card-label">Agenten-Aufrufe</span>
                <span class="pl-${ctx.id}__card-value" id="pl-${ctx.id}__agent-calls">0</span>
              </div>
            </div>
          </div>
        </section>

        <section class="pl-${ctx.id}__section">
          <h2>Protokoll</h2>
          <div class="pl-${ctx.id}__log" id="pl-${ctx.id}__log">
            <div class="pl-${ctx.id}__log-empty">Keine Ereignisse – Engine läuft normal.</div>
          </div>
          <div class="pl-${ctx.id}__actions">
            <button class="pl-${ctx.id}__btn" id="pl-${ctx.id}__refresh">
              ${host.ui.icon("refresh-cw")} Aktualisieren
            </button>
            <button class="pl-${ctx.id}__btn pl-${ctx.id}__btn--secondary" id="pl-${ctx.id}__clear">
              ${host.ui.icon("trash-2")} Protokoll leeren
            </button>
          </div>
        </section>

        <section class="pl-${ctx.id}__section">
          <h2>Engine-Konfiguration</h2>
          <div class="pl-${ctx.id}__config">
            <label class="pl-${ctx.id}__toggle">
              <input type="checkbox" id="pl-${ctx.id}__auto-review" checked />
              <span class="pl-${ctx.id}__toggle-slider"></span>
              <span>Auto-Review bei 100% Completion</span>
            </label>
            <label class="pl-${ctx.id}__toggle">
              <input type="checkbox" id="pl-${ctx.id}__loop-detect" checked />
              <span class="pl-${ctx.id}__toggle-slider"></span>
              <span>Planning-Loop-Erkennung</span>
            </label>
            <label class="pl-${ctx.id}__toggle">
              <input type="checkbox" id="pl-${ctx.id}__delegate-limit" checked />
              <span class="pl-${ctx.id}__toggle-slider"></span>
              <span>Delegations-Limit (max 3)</span>
            </label>
          </div>
        </section>
      </div>
    `;

    // Event-Handler
    const refreshBtn = el.querySelector(`#pl-${ctx.id}__refresh`);
    const clearBtn = el.querySelector(`#pl-${ctx.id}__clear`);
    const autoReviewCb = el.querySelector(`#pl-${ctx.id}__auto-review`);
    const loopDetectCb = el.querySelector(`#pl-${ctx.id}__loop-detect`);
    const delegateLimitCb = el.querySelector(`#pl-${ctx.id}__delegate-limit`);

    refreshBtn?.addEventListener("click", () => {
      addLogEntry("Manuelle Aktualisierung ausgelöst", "info");
      updateStats();
    });

    clearBtn?.addEventListener("click", () => {
      const logEl = el.querySelector(`#pl-${ctx.id}__log`);
      if (logEl) logEl.innerHTML = `<div class="pl-${ctx.id}__log-empty">Protokoll geleert.</div>`;
    });

    autoReviewCb?.addEventListener("change", (e) => {
      addLogEntry(`Auto-Review ${e.target.checked ? "aktiviert" : "deaktiviert"}`, "config");
    });

    loopDetectCb?.addEventListener("change", (e) => {
      addLogEntry(`Loop-Erkennung ${e.target.checked ? "aktiviert" : "deaktiviert"}`, "config");
    });

    delegateLimitCb?.addEventListener("change", (e) => {
      addLogEntry(`Delegations-Limit ${e.target.checked ? "aktiviert" : "deaktiviert"}`, "config");
    });

    function addLogEntry(message, type = "info") {
      const logEl = el.querySelector(`#pl-${ctx.id}__log`);
      if (!logEl) return;
      const empty = logEl.querySelector(".pl-" + ctx.id + "__log-empty");
      if (empty) empty.remove();
      const entry = document.createElement("div");
      entry.className = `pl-${ctx.id}__log-entry pl-${ctx.id}__log-entry--${type}`;
      const time = new Date().toLocaleTimeString("de-DE");
      entry.innerHTML = `<span class="pl-${ctx.id}__log-time">${time}</span><span class="pl-${ctx.id}__log-msg">${message}</span>`;
      logEl.prepend(entry);
    }

    function updateStats() {
      // Hier könnten echte Engine-Statistiken abgerufen werden
      // Für jetzt simulierte Werte
      document.getElementById(`pl-${ctx.id}__active-goals`).textContent = "0";
      document.getElementById(`pl-${ctx.id}__review-blocked`).textContent = "0";
      document.getElementById(`pl-${ctx.id}__planning-loops`).textContent = "0";
      document.getElementById(`pl-${ctx.id}__agent-calls`).textContent = "0";
    }

    updateStats();

    return { 
      dispose() { 
        el.innerHTML = ""; 
      },
      addLogEntry 
    };
  } }));
  return () => off.forEach((f) => f());
}
